import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Account source = new Account(Long.parseLong(sc.next()));
        Account destination = new Account(Long.parseLong(sc.next()));
        long amount = Long.parseLong(sc.next());
        try {
            source.transferTo(destination, amount);
            System.out.println("Transfer successful");
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        } catch (InsufficientFundsException e) {
            System.out.println(e.getMessage());
        } catch (ArithmeticException e) {
            System.out.println(e.getMessage());
        }
        System.out.println("Source balance: " + source.getBalance());
        System.out.println("Destination balance: " + destination.getBalance());
    }
}

class InsufficientFundsException extends Exception {
    InsufficientFundsException(String message) {
        super(message);
    }
}

class Account {
    private long balance;

    Account(long balance) {
        this.balance = balance;
    }

    public long getBalance() {
        return balance;
    }

    public void transferTo(Account destination, long amount) throws InsufficientFundsException {
        if (amount <= 0) {
            throw new IllegalArgumentException("Invalid transfer amount");
        }
        if (balance < amount) {
            throw new InsufficientFundsException("Insufficient funds");
        }
        if (destination.balance > Long.MAX_VALUE - amount) {
            throw new ArithmeticException("Balance overflow");
        }
        balance -= amount;
        destination.balance += amount;
    }
}

