public class Main {
    static void attempt(int attemptNumber, int failuresBeforeSuccess) {
        if (attemptNumber <= failuresBeforeSuccess) {
            throw new IllegalStateException("Temporary service failure");
        }
    }

    static void performWithRetries(int failuresBeforeSuccess, int maxAttempts) throws RetryLimitExceededException {
        for (int attemptNumber = 1; attemptNumber <= maxAttempts; attemptNumber++) {
            try {
                attempt(attemptNumber, failuresBeforeSuccess);
                System.out.println("Attempt " + attemptNumber + ": Success");
                return;
            } catch (IllegalStateException e) {
                System.out.println("Attempt " + attemptNumber + ": " + e.getMessage());
            }
        }
        throw new RetryLimitExceededException("Retry limit exceeded");
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int f = Integer.parseInt(sc.next());
        int a = Integer.parseInt(sc.next());
        try {
            performWithRetries(f, a);
        } catch (RetryLimitExceededException e) {
            System.out.println(e.getMessage());
        }
    }
}

