public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Inventory inventory = new Inventory(Long.parseLong(sc.next()));
        int q = Integer.parseInt(sc.next());
        for (int i = 0; i < q; i++) {
            long change = Long.parseLong(sc.next());
            try {
                inventory.update(change);
                System.out.println("Updated: " + inventory.getQuantity());
            } catch (InvalidInventoryOperationException e) {
                System.out.println(e.getMessage());
            } catch (ArithmeticException e) {
                System.out.println(e.getMessage());
            }
        }
    }
}

class InvalidInventoryOperationException extends Exception {
    InvalidInventoryOperationException(String message) {
        super(message);
    }
}

class Inventory {
    private long quantity;

    Inventory(long quantity) {
        this.quantity = quantity;
    }

    public long getQuantity() {
        return quantity;
    }

    public void update(long change) throws InvalidInventoryOperationException {
        if (change == 0) {
            throw new InvalidInventoryOperationException("Change cannot be zero");
        }
        if (change < 0 && change < -quantity) {
            throw new InvalidInventoryOperationException("Insufficient inventory");
        }
        if (change > 0 && change > Long.MAX_VALUE - quantity) {
            throw new ArithmeticException("Inventory overflow");
        }
        quantity += change;
    }
}
